new = '''def _decompose_trees(root, total, lv, parts):
    """Split the pair-demand dict lv into arborescence records for `root`."""
    C = [v for (v, _rv) in parts]
    work = {}
    for k, val in lv.items():
        if val > 0:
            work[k] = val
    recs = []
    left = total
    guard = 0
    while left > 0:
        guard += 1
        if guard > 20000 or len(recs) > 8100:
            return None
        placed = set([root])
        parents = {}
        while len(placed) < len(C):
            best = None
            for w in C:
                if w in placed:
                    continue
                for u in placed:
                    val = work.get((u, w), 0)
                    if val > 0 and (best is None or val > best[0]):
                        best = (val, u, w)
            if best is None:
                return None
            _val, u, w = best
            parents[w] = u
            placed.add(w)
        cnt = min([work[(parents[w], w)] for w in parents] + [left])
        if cnt <= 0:
            return None
        recs.append([root, cnt, [[parents[w], w] for w in parents]])
        for w in parents:
            work[(parents[w], w)] -= cnt
            if work[(parents[w], w)] <= 0:
                del work[(parents[w], w)]
        left -= cnt
    if left != 0:
        return None
    return recs


'''
src = src[:start] + new + src[end:]
